class Counter:
    LIMIT = 9

    def __init__(self, value=0):
        self.v = value

    @classmethod
    def zero(cls):
        return cls(0)

    def __repr__(self):
        return "Counter(%s)" % (self.v,)

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, tb):
        return False

    def __setitem__(self, key, value):
        self.v = value

    def __getitem__(self, key):
        return self.v

